const config = $input.first().json;

const schedule = (config.Reporting_Schedule || 'Weekly').toLowerCase();
let daysBack = 7;
let datePreset = 'last_7d';
if (schedule === 'biweekly') { daysBack = 14; datePreset = 'last_14d'; }
else if (schedule === 'monthly') { daysBack = 30; datePreset = 'last_30d'; }

const now = new Date();
const until = new Date(now);
until.setDate(until.getDate() - 1);
until.setHours(23, 59, 59, 999);

const since = new Date(until);
since.setDate(since.getDate() - (daysBack - 1));
since.setHours(0, 0, 0, 0);

const fmt = (d) => d.toISOString().split('T')[0];
const weekLabel = `${fmt(since)} to ${fmt(until)}`;

return [{
  json: {
    since: fmt(since),
    until: fmt(until),
    date_preset: datePreset,
    days_back: daysBack,
    week_label: weekLabel,
    data: {
      Meta_Ads_Account_ID: config.Meta_Ads_Account_ID,
      Meta_Access_Token: config.Meta_Access_Token,
      Report_Email: config.Report_Email,
      Reporting_Schedule: config.Reporting_Schedule,
      Company_Name: config.Company_Name
    }
  }
}];

const resp = $input.first().json;
const rows = resp.data || [];

const campaignsMap = {};
const dailyTotals = {};

function getAction(actions, type) {
  if (!Array.isArray(actions)) return 0;
  const found = actions.find(a => a.action_type === type);
  return found ? parseFloat(found.value) : 0;
}
function getActionValue(actionValues, type) {
  if (!Array.isArray(actionValues)) return 0;
  const found = actionValues.find(a => a.action_type === type);
  return found ? parseFloat(found.value) : 0;
}

let totalSpend = 0, totalImpressions = 0, totalClicks = 0, totalReach = 0, totalResults = 0, totalRevenue = 0;

rows.forEach(row => {
  const name = row.campaign_name || 'Unknown Campaign';
  const spend = parseFloat(row.spend || 0);
  const impressions = parseInt(row.impressions || 0);
  const clicks = parseInt(row.clicks || 0);
  const reach = parseInt(row.reach || 0);
  const date = row.date_start;

  const purchases = getAction(row.actions, 'purchase') || getAction(row.actions, 'omni_purchase');
  const leads = getAction(row.actions, 'lead');
  const landingPageViews = getAction(row.actions, 'landing_page_view');
  const linkClicks = getAction(row.actions, 'link_click');
  const results = purchases || leads || landingPageViews || linkClicks || 0;
  const revenue = getActionValue(row.action_values, 'purchase') || getActionValue(row.action_values, 'omni_purchase') || 0;

  if (!campaignsMap[name]) {
    campaignsMap[name] = { campaign_id: row.campaign_id, campaign_name: name, spend: 0, impressions: 0, clicks: 0, reach: 0, results: 0, revenue: 0 };
  }
  const c = campaignsMap[name];
  c.spend += spend;
  c.impressions += impressions;
  c.clicks += clicks;
  c.reach = Math.max(c.reach, reach);
  c.results += results;
  c.revenue += revenue;

  if (!dailyTotals[date]) dailyTotals[date] = { date, spend: 0, impressions: 0, clicks: 0 };
  dailyTotals[date].spend += spend;
  dailyTotals[date].impressions += impressions;
  dailyTotals[date].clicks += clicks;

  totalSpend += spend;
  totalImpressions += impressions;
  totalClicks += clicks;
  totalReach += reach;
  totalResults += results;
  totalRevenue += revenue;
});

const campaigns = Object.values(campaignsMap).map(c => ({
  campaign_id: c.campaign_id,
  campaign_name: c.campaign_name,
  spend: Math.round(c.spend * 100) / 100,
  impressions: c.impressions,
  clicks: c.clicks,
  reach: c.reach,
  results: Math.round(c.results),
  revenue: Math.round(c.revenue * 100) / 100,
  ctr: c.impressions > 0 ? Math.round((c.clicks / c.impressions) * 10000) / 100 : 0,
  cpc: c.clicks > 0 ? Math.round((c.spend / c.clicks) * 100) / 100 : 0,
  cost_per_result: c.results > 0 ? Math.round((c.spend / c.results) * 100) / 100 : 0,
  roas: (c.spend > 0 && c.revenue > 0) ? Math.round((c.revenue / c.spend) * 100) / 100 : null
})).sort((a, b) => b.spend - a.spend);

const dailySeries = Object.values(dailyTotals).sort((a, b) => a.date.localeCompare(b.date));

const summary = {
  total_spend: Math.round(totalSpend * 100) / 100,
  total_impressions: totalImpressions,
  total_clicks: totalClicks,
  total_reach: totalReach,
  total_results: Math.round(totalResults),
  total_revenue: Math.round(totalRevenue * 100) / 100,
  avg_ctr: totalImpressions > 0 ? Math.round((totalClicks / totalImpressions) * 10000) / 100 : 0,
  avg_cpc: totalClicks > 0 ? Math.round((totalSpend / totalClicks) * 100) / 100 : 0,
  avg_cpm: totalImpressions > 0 ? Math.round(((totalSpend / totalImpressions) * 1000) * 100) / 100 : 0,
  avg_cost_per_result: totalResults > 0 ? Math.round((totalSpend / totalResults) * 100) / 100 : 0,
  overall_roas: (totalSpend > 0 && totalRevenue > 0) ? Math.round((totalRevenue / totalSpend) * 100) / 100 : null,
  campaign_count: campaigns.length
};

return [{ json: { data: { campaigns, dailySeries, summary } } }];

const rows = $input.first().json.data || [];
const accessToken = $node["Calculate Dates and Wrap Data"].json.data.Meta_Access_Token;

function getAction(actions, type) {
  if (!Array.isArray(actions)) return 0;
  const found = actions.find(a => a.action_type === type);
  return found ? parseFloat(found.value) : 0;
}

const results = [];

for (const ad of rows) {
  let creative = {};
  try {
    const resp = await this.helpers.request({
      method: 'GET',
      uri: `https://graph.facebook.com/v23.0/${ad.ad_id}`,
      qs: {
        fields: 'creative{thumbnail_url,image_url,body,title,object_type}',
        access_token: accessToken
      },
      json: true
    });
    creative = resp.creative || {};
  } catch (error) {
    creative = { error: error.message };
  }

  const spend = parseFloat(ad.spend || 0);
  const impressions = parseInt(ad.impressions || 0);
  const clicks = parseInt(ad.clicks || 0);
  const purchases = getAction(ad.actions, 'purchase') || getAction(ad.actions, 'omni_purchase');
  const leads = getAction(ad.actions, 'lead');
  const linkClicks = getAction(ad.actions, 'link_click');
  const resultsCount = purchases || leads || linkClicks || 0;

  results.push({
    json: {
      ad_id: ad.ad_id,
      ad_name: ad.ad_name || 'Untitled Ad',
      adset_name: ad.adset_name || '',
      campaign_name: ad.campaign_name || '',
      spend: Math.round(spend * 100) / 100,
      impressions,
      clicks,
      ctr: parseFloat(ad.ctr || 0),
      cpc: parseFloat(ad.cpc || 0),
      results: Math.round(resultsCount),
      cost_per_result: resultsCount > 0 ? Math.round((spend / resultsCount) * 100) / 100 : 0,
      thumbnail_url: creative.thumbnail_url || creative.image_url || '',
      body: creative.body || '',
      title: creative.title || ''
    }
  });
}

return results;

const ads = $input.all().map(i => i.json);

const sorted = [...ads].sort((a, b) => b.spend - a.spend);

const bestCtr = ads.reduce((best, a) => (a.ctr > (best?.ctr || 0) ? a : best), null);
const bestSpend = sorted[0] || null;

const summary = {
  ads_analyzed: ads.length,
  best_ctr_ad: bestCtr ? bestCtr.ad_name : 'N/A',
  best_ctr_value: bestCtr ? bestCtr.ctr : 0,
  top_spend_ad: bestSpend ? bestSpend.ad_name : 'N/A',
  top_spend_value: bestSpend ? bestSpend.spend : 0
};

return [{ json: { data: { ads: sorted, summary } } }];

const campaignData = $node["Organize Campaign Data"].json.data;
const adData = $node["Organize Ad Creative Data"].json.data;
const accountInfo = $node["Get Ad Account Info"].json;
const weekLabel = $node["Calculate Dates and Wrap Data"].json.week_label;
const since = $node["Calculate Dates and Wrap Data"].json.since;
const until = $node["Calculate Dates and Wrap Data"].json.until;
const companyName = $node["Calculate Dates and Wrap Data"].json.data.Company_Name || accountInfo.name || 'Your Brand';
const currency = accountInfo.currency || 'USD';

function chartUrl(config, width, height) {
  let url = `https://quickchart.io/chart?c=${encodeURIComponent(JSON.stringify(config))}`;
  if (width && height) url += `&width=${width}&height=${height}`;
  return url;
}

function generateLineChart(labels, datasets, title) {
  return {
    type: "line",
    data: { labels, datasets: datasets.map(d => ({ tension: 0.4, pointRadius: 3, fill: false, ...d })) },
    options: { responsive: true, plugins: { title: { display: true, text: title, font: { size: 16 } } }, scales: { y: { beginAtZero: true } } }
  };
}

function generateBarChart(labels, data, label, title, color) {
  return {
    type: "bar",
    data: { labels, datasets: [{ label, data, backgroundColor: color }] },
    options: { responsive: true, plugins: { title: { display: true, text: title, font: { size: 16 } }, legend: { display: false } }, scales: { y: { beginAtZero: true } } }
  };
}

const dates = campaignData.dailySeries.map(d => d.date.slice(5));
const spendData = campaignData.dailySeries.map(d => Math.round(d.spend * 100) / 100);
const impressionsData = campaignData.dailySeries.map(d => d.impressions);
const clicksData = campaignData.dailySeries.map(d => d.clicks);
const ctrData = campaignData.dailySeries.map(d => d.impressions > 0 ? Math.round((d.clicks / d.impressions) * 10000) / 100 : 0);

const spendChartUrl = chartUrl(generateLineChart(dates, [
  { label: 'Spend', data: spendData, borderColor: '#e94560', backgroundColor: '#e9456022', fill: true }
], 'Daily Ad Spend'), 700, 300);

const clicksImpressionsChartUrl = chartUrl(generateLineChart(dates, [
  { label: 'Impressions', data: impressionsData, borderColor: '#1877F2' },
  { label: 'Clicks', data: clicksData, borderColor: '#42B72A' }
], 'Impressions vs Clicks'), 700, 300);

const topCampaigns = campaignData.campaigns.slice(0, 6);
const campaignSpendChartUrl = chartUrl(generateBarChart(
  topCampaigns.map(c => c.campaign_name.slice(0, 18)),
  topCampaigns.map(c => c.spend),
  'Spend', 'Top Campaigns by Spend', '#0f3460'
), 700, 320);

const ctrChartUrl = chartUrl(generateLineChart(dates, [
  { label: 'CTR %', data: ctrData, borderColor: '#833AB4', backgroundColor: '#833AB422', fill: true }
], 'Daily CTR Trend'), 700, 300);

return [{ json: {
  weekLabel, since, until, companyName, currency,
  campaignData, adData,
  charts: { spendChartUrl, clicksImpressionsChartUrl, campaignSpendChartUrl, ctrChartUrl }
}}];

const merged = $input.first().json;
const c = merged.campaignData;
const a = merged.adData;

const systemPrompt = `You are a professional paid media analyst specializing in Meta Ads (Facebook & Instagram advertising). Analyze weekly campaign performance data. Always respond in English. You MUST use these EXACT section headers with ### prefix, nothing else before the content:

### EXECUTIVE SUMMARY
### CAMPAIGN PERFORMANCE ANALYSIS
### CREATIVE PERFORMANCE ANALYSIS
### BUDGET & EFFICIENCY INSIGHTS
### NEXT STEPS

Under NEXT STEPS, write exactly 4 items each starting with "\u2022 " on its own line. Do not add numbered prefixes, markdown bold, or extra formatting.`;

const userPrompt = `Analyze this Meta Ads performance data for the period ${merged.since} to ${merged.until} (currency: ${merged.currency}):

ACCOUNT SUMMARY:
- Total Spend: ${c.summary.total_spend}
- Total Impressions: ${c.summary.total_impressions}
- Total Clicks: ${c.summary.total_clicks}
- Total Reach: ${c.summary.total_reach}
- Total Results: ${c.summary.total_results}
- Average CTR: ${c.summary.avg_ctr}%
- Average CPC: ${c.summary.avg_cpc}
- Average CPM: ${c.summary.avg_cpm}
- Average Cost Per Result: ${c.summary.avg_cost_per_result}
- Overall ROAS: ${c.summary.overall_roas ?? 'N/A'}
- Active Campaigns: ${c.summary.campaign_count}

TOP CAMPAIGNS: ${JSON.stringify(c.campaigns.slice(0, 5).map(x => ({ name: x.campaign_name, spend: x.spend, ctr: x.ctr, cpc: x.cpc, results: x.results, cost_per_result: x.cost_per_result })))}

TOP AD CREATIVES: ${JSON.stringify(a.ads.slice(0, 5).map(x => ({ name: x.ad_name, spend: x.spend, ctr: x.ctr, results: x.results, cost_per_result: x.cost_per_result })))}

Respond now:`;

return [{ json: { systemPrompt, userPrompt, merged } }];

const geminiRaw = $node["Message a model"].json;

const aiResponse =
  (Array.isArray(geminiRaw) ? geminiRaw[0] : geminiRaw)
    ?.content?.parts?.[0]?.text ||
  geminiRaw?.candidates?.[0]?.content?.parts?.[0]?.text ||
  geminiRaw?.message?.content ||
  "";

const merged = $node["Merge All Data & Build Charts"].json;
const c = merged.campaignData;
const a = merged.adData;
const charts = merged.charts;
const weekLabel = merged.weekLabel;
const companyName = merged.companyName;
const currency = merged.currency;

function extractSection(text, heading) {
  const escaped = heading.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regex = new RegExp(`###\\s*${escaped}\\s*\\n([\\s\\S]*?)(?=###|$)`, 'i');
  const match = text.match(regex);
  return match ? match[1].trim() : '';
}

const execSummary   = extractSection(aiResponse, 'EXECUTIVE SUMMARY')   || 'Analysis unavailable for this period.';
const campAnalysis  = extractSection(aiResponse, 'CAMPAIGN PERFORMANCE ANALYSIS') || 'No campaign analysis available.';
const creativeAnalysis = extractSection(aiResponse, 'CREATIVE PERFORMANCE ANALYSIS') || 'No creative analysis available.';
const budgetInsights = extractSection(aiResponse, 'BUDGET & EFFICIENCY INSIGHTS') || 'No budget insights available.';
const nextStepsRaw  = extractSection(aiResponse, 'NEXT STEPS') || '';

const stepLines = nextStepsRaw
  .split('\n')
  .map(l => l.replace(/^[\u2022\-\*]\s*/, '').trim())
  .filter(l => l.length > 10)
  .slice(0, 4);

while (stepLines.length < 4) stepLines.push('Review campaign performance and adjust budget allocation accordingly.');

const esc = (str) => String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fmtMoney = (n) => `${currency} ${Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const campaignRowsHtml = c.campaigns.length === 0
  ? '<tr><td colspan="7" style="text-align:center;color:#6b7280;padding:16px;">No campaign activity this period.</td></tr>'
  : c.campaigns.map(camp => `
    <tr>
      <td>${esc(camp.campaign_name)}</td>
      <td>${fmtMoney(camp.spend)}</td>
      <td>${camp.impressions.toLocaleString()}</td>
      <td>${camp.clicks.toLocaleString()}</td>
      <td>${camp.ctr}%</td>
      <td>${fmtMoney(camp.cpc)}</td>
      <td>${camp.results.toLocaleString()}</td>
    </tr>`).join('');

const creativeCardsHtml = a.ads.length === 0
  ? '<p style="color:#6b7280;font-size:13px;">No ad creative data available this period.</p>'
  : a.ads.map(ad => `
    <div class="creative-card" style="break-inside:avoid;">
      ${ad.thumbnail_url ? `<div class="creative-thumb" style="background-image:url('${esc(ad.thumbnail_url)}')"></div>` : '<div class="creative-thumb creative-thumb-placeholder">\ud83c\udfaf</div>'}
      <div class="creative-body">
        <div class="creative-meta">${esc(ad.campaign_name)}</div>
        <p class="creative-text">${esc((ad.ad_name || 'Untitled Ad').slice(0, 80))}</p>
        <div class="creative-stats">
          <span class="cstat">${fmtMoney(ad.spend)} spend</span>
          <span class="cstat">${ad.ctr}% CTR</span>
          <span class="cstat">${ad.results} results</span>
        </div>
      </div>
    </div>`).join('');

const nextStepCardsHtml = stepLines.map((step, i) => `
  <div class="step-card" style="break-inside:avoid;">
    <div class="step-num">${i + 1}</div>
    <p class="step-text">${esc(step)}</p>
  </div>`).join('');

