  .campaign-table tr:nth-child(even) { background:#f8f9ff; }

  .creative-grid { display:flex; flex-wrap:wrap; gap:16px; margin-top:20px; }
  .creative-card { flex:1 1 calc(33% - 11px); min-width:200px; background:#fff; border:1px solid #e8eaf6; border-radius:12px; overflow:hidden; break-inside:avoid; }
  .creative-thumb { width:100%; height:130px; background-size:cover; background-position:center; background-color:#f0f2f5; }
